    ('c4a86b95-21a5-4b09-892b-318d63c04cbf', v_uni_id, 'CDIC2006W', 'Data & Survey Techniques 1', 'CDIC', null, 'https://www.ucd.ie/modules/CDIC2006W', 'cdic2006w'),
    ('ea1eb4cd-e746-4789-a125-b895a36c5409', v_uni_id, 'CDIC2008W', 'Traffic Psychology & Ergonomics', 'CDIC', null, 'https://www.ucd.ie/modules/CDIC2008W', 'cdic2008w'),
    ('50e3ba21-18e7-4972-8b92-e081968f73b2', v_uni_id, 'CDIC2009W', 'Engineering Geology', 'CDIC', 'This is a professional foundation course, which introduced the types of rock and soil, geological processes, geological structure, landform, groundwater, and bad geological phenomenon effect on engineering construction. This course aims at providing essential engineering geological knowledge for the High-Level Technical Personnel of Highway & Bridge Engineering.', 'https://www.ucd.ie/modules/CDIC2009W', 'cdic2009w'),
    ('38573e85-a542-41d2-a4ff-2265c11ddaa0', v_uni_id, 'CDIC2011W', 'Manufacturing Engineering 1', 'CDIC', null, 'https://www.ucd.ie/modules/CDIC2011W', 'cdic2011w'),
